/* 最小 MQTT CONNECT，然后等 CONNACK（0x20 0x02 0x00 <rc>） */
static int mqtt_handshake(int fd, const char *client_id)
{
  uint8_t pkt[64];
  uint8_t resp[8];
  int pos = 0, n;
  int cidlen = strlen(client_id);

  pkt[pos++] = 0x10;                 /* CONNECT */
  pkt[pos++] = 12 + cidlen;          /* remaining length */
  pkt[pos++] = 0x00; pkt[pos++] = 0x04;
  memcpy(&pkt[pos], "MQTT", 4); pos += 4;
  pkt[pos++] = 0x04;                 /* protocol level 3.1.1 */
  pkt[pos++] = 0x02;                 /* clean session */
  pkt[pos++] = 0x00; pkt[pos++] = 0x3C;   /* keepalive 60s */
  pkt[pos++] = (cidlen >> 8) & 0xFF;
  pkt[pos++] = cidlen & 0xFF;
  memcpy(&pkt[pos], client_id, cidlen); pos += cidlen;

  if (send(fd, pkt, pos, 0) != pos) return -1;

  n = recv(fd, resp, sizeof(resp), 0);
  if (n < 4) return -1;
  if ((resp[0] & 0xF0) != 0x20) return -1;   /* 不是 CONNACK */
  return resp[3];                             /* 0 = 接受 */
}
